// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

// Custom sanitization function to prevent XSS
const sanitizeString = (value) => {
  if (typeof value !== 'string') return value;
  // Remove potential XSS patterns
  return value
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
};

// Validation middleware wrapper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================
// ROUTES WITH VALIDATION
// ============================================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app, this would come from a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// Example route with proper validation
app.get('/users/:id',
  [
    param('id')
      .trim()
      .isInt({ min: 1, max: Number.MAX_SAFE_INTEGER })
      .withMessage('ID must be a positive integer')
      .toInt(),
    validate,
  ],
  (req, res) => {
    const userId = req.params.id;
    // Safe to use userId after validation
    res.json({ id: userId, name: 'User ' + userId });
  }
);

// Example POST route with validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters')
      .escape(), // Escape HTML entities
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 }).withMessage('Email too long'),
    validate,
  ],
  (req, res) => {
    const { name, email } = req.body;
    // Input is validated and sanitized
    res.status(201).json({ 
      message: 'User created', 
      user: { name, email } 
    });
  }
);

// Example with query parameter validation
app.get('/search',
  [
    query('q')
      .trim()
      .notEmpty().withMessage('Search query is required')
      .isLength({ max: 100 }).withMessage('Query too long')
      .escape(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 }).withMessage('Limit must be 1-100')
      .toInt(),
    validate,
  ],
  (req, res) => {
    const { q, limit = 10 } = req.query;
    res.json({ query: q, limit, results: [] });
  }
);

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler - MUST be last
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error('Error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Handle specific error types
  if (err.type === 'entity.too.large') {
    return res.status(413).json({ error: 'Request entity too large' });
  }

  if (err.name === 'SyntaxError') {
    return res.status(400).json({ error: 'Invalid JSON payload' });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Generic error response
  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

// Only start server if this file is run directly
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

