// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const app = express();

// =============================================================================
// SECURITY MIDDLEWARE
// =============================================================================

// Set security-related HTTP headers
app.use(helmet());

// Parse JSON bodies with limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// =============================================================================
// INPUT VALIDATION UTILITIES
// =============================================================================

/**
 * Validates and sanitizes user input
 * @param {string} input - The input to validate
 * @param {number} maxLength - Maximum allowed length
 * @returns {boolean} - Whether input is valid
 */
function validateInput(input, maxLength = 255) {
  if (typeof input !== 'string') return false;
  if (input.length === 0 || input.length > maxLength) return false;
  // Check for potentially dangerous patterns
  const dangerousPatterns = /[<>]/; // Basic XSS detection
  return !dangerousPatterns.test(input);
}

/**
 * Validates email format
 * @param {string} email - Email to validate
 * @returns {boolean} - Whether email is valid
 */
function validateEmail(email) {
  if (typeof email !== 'string') return false;
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email) && email.length <= 254;
}

/**
 * Validates numeric ID parameter
 * @param {any} id - ID to validate
 * @returns {number|null} - Parsed ID or null if invalid
 */
function validateId(id) {
  const parsed = parseInt(id, 10);
  if (isNaN(parsed) || parsed < 1 || parsed > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  return parsed;
}

// =============================================================================
// ROUTES
// =============================================================================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example route with input validation
app.get('/users/:id', (req, res) => {
  const id = validateId(req.params.id);

  if (id === null) {
    return res.status(400).json({ 
      error: 'Invalid ID format',
      message: 'ID must be a positive integer'
    });
  }

  // In a real app, fetch user from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === id);

  if (!user) {
    return res.status(404).json({ 
      error: 'User not found',
      message: `No user exists with ID ${id}`
    });
  }

  res.json(user);
});

// Example POST route with validation
app.post('/users', (req, res) => {
  const { name, email } = req.body;

  // Input validation
  if (!name || !validateInput(name, 100)) {
    return res.status(400).json({
      error: 'Invalid name',
      message: 'Name must be 1-100 characters and cannot contain < or >'
    });
  }

  if (!email || !validateEmail(email)) {
    return res.status(400).json({
      error: 'Invalid email',
      message: 'Email must be a valid email address'
    });
  }

  // In a real app, sanitize and save to database
  res.status(201).json({
    id: Date.now(),
    name: name.trim(),
    email: email.toLowerCase().trim()
  });
});

// =============================================================================
// ERROR HANDLING
// =============================================================================

// 404 handler - must come after all routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} does not exist`
  });
});

// Global error handler - must have 4 parameters
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error(`[${new Date().toISOString()}] Error:`, err.message);

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  // Handle specific error types
  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      error: 'Payload Too Large',
      message: 'Request body exceeds size limit'
    });
  }

  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON in request body'
    });
  }

  // Generic error response
  res.status(err.status || 500).json({
    error: err.status === 500 ? 'Internal Server Error' : err.message,
    message: isProduction ? 'An unexpected error occurred' : err.message,
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// =============================================================================
// SERVER STARTUP
// =============================================================================

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

function gracefulShutdown() {
  console.log('\nReceived shutdown signal. Closing server gracefully...');

  server.close(() => {
    console.log('Server closed. Exiting process.');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
}

module.exports = app;

