// Simple application with improved error handling and security
// Security best practices implementation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting - prevents brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with limits to prevent payload attacks
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

/**
 * Validate and sanitize user ID
 * @param {any} id - Input to validate
 * @returns {number|null} - Validated ID or null if invalid
 */
function validateUserId(id) {
  const parsed = parseInt(id, 10);
  if (isNaN(parsed) || parsed < 1 || parsed > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  return parsed;
}

/**
 * Validate email format
 * @param {string} email - Email to validate
 * @returns {boolean} - True if valid email format
 */
function validateEmail(email) {
  if (typeof email !== 'string' || email.length > 254) {
    return false;
  }
  // RFC 5322 compliant email regex (simplified)
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

/**
 * Sanitize string input - remove potential XSS vectors
 * @param {string} input - Input to sanitize
 * @param {number} maxLength - Maximum allowed length
 * @returns {string} - Sanitized string
 */
function sanitizeString(input, maxLength = 255) {
  if (typeof input !== 'string') {
    return '';
  }
  // Trim and limit length
  let sanitized = input.trim().slice(0, maxLength);
  // Escape HTML entities to prevent XSS
  sanitized = sanitized
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
  return sanitized;
}

/**
 * Validate pagination parameters
 * @param {any} page - Page number
 * @param {any} limit - Items per page
 * @returns {object} - Validated pagination object
 */
function validatePagination(page, limit) {
  const validatedPage = Math.max(1, parseInt(page, 10) || 1);
  const validatedLimit = Math.min(100, Math.max(1, parseInt(limit, 10) || 10));
  return { page: validatedPage, limit: validatedLimit };
}

// ============================================
// ERROR HANDLING
// ============================================

/**
 * Custom application error class
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Async handler wrapper to catch errors in async routes
 * @param {Function} fn - Async function to wrap
 * @returns {Function} - Express middleware
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Example users data (in production, this would come from a database)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// Example route with parameter validation
app.get('/users/:id', asyncHandler(async (req, res, next) => {
  const userId = validateUserId(req.params.id);

  if (!userId) {
    return next(new AppError('Invalid user ID format', 400));
  }

  // In production, fetch from database with parameterized queries
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return next(new AppError('User not found', 404));
  }

  res.json(user);
}));

// Example POST route with input validation
app.post('/users', asyncHandler(async (req, res, next) => {
  const { name, email } = req.body;

  // Validate required fields
  if (!name || !email) {
    return next(new AppError('Name and email are required', 400));
  }

  // Validate and sanitize inputs
  const sanitizedName = sanitizeString(name, 100);
  const isValidEmail = validateEmail(email);

  if (!sanitizedName || sanitizedName.length < 2) {
    return next(new AppError('Invalid name format', 400));
  }

  if (!isValidEmail) {
    return next(new AppError('Invalid email format', 400));
  }

  // In production, use parameterized queries for database operations
  const newUser = {
    id: Date.now(), // Use proper ID generation in production
    name: sanitizedName,
    email: email.toLowerCase().trim(),
  };

  res.status(201).json(newUser);
}));

// Query parameter validation example
app.get('/search', asyncHandler(async (req, res, next) => {
  const { q, page, limit } = req.query;

  if (!q || typeof q !== 'string') {
    return next(new AppError('Search query "q" is required', 400));
  }

  const sanitizedQuery = sanitizeString(q, 100);
  const pagination = validatePagination(page, limit);

  // In production, use parameterized queries with database
  res.json({
    query: sanitizedQuery,
    pagination,
    results: [],
  });
}));

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res, next) => {
  next(new AppError(`Cannot find ${req.method} ${req.originalUrl}`, 404));
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Default error values
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Don't leak error details in production
  const response = {
    status: err.status,
    message: err.isOperational ? err.message : 'An unexpected error occurred',
  };

  // Include stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(err.statusCode).json(response);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! Shutting down...', err);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...', err);
  process.exit(1);
});

module.exports = app;

