// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers using helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: 'same-origin' },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: 'none' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true,
}));

// Rate limiting to prevent DoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  // Use IP from X-Forwarded-For if behind a proxy (configure trust proxy)
  // trustProxy: true, // Uncomment if behind a reverse proxy
});
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // Only 5 requests per hour
  message: { error: 'Too many attempts. Please try again later.' },
});

// Request logging for audit trail
app.use(morgan('combined'));

// Body parsing with limits
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent large payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// VALIDATION UTILITIES
// ============================================

// Custom validation result handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Sanitization helper - remove null bytes and trim strings
const sanitizeString = (value) => {
  if (typeof value !== 'string') return value;
  return value.replace(/\0/g, '').trim();
};

// Input validation schemas
const userIdSchema = [
  param('id')
    .notEmpty().withMessage('User ID is required')
    .isInt({ min: 1, max: Number.MAX_SAFE_INTEGER }).withMessage('User ID must be a positive integer')
    .toInt(),
  handleValidationErrors,
];

const userQuerySchema = [
  query('page')
    .optional()
    .isInt({ min: 1, max: 10000 }).withMessage('Page must be between 1 and 10000')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('search')
    .optional()
    .isLength({ max: 100 }).withMessage('Search term too long')
    .customSanitizer(sanitizeString)
    .escape(), // Escape HTML entities
  handleValidationErrors,
];

// ============================================
// ERROR HANDLING
// ============================================

// Custom error classes
class AppError extends Error {
  constructor(message, statusCode, errorCode = null) {
    super(message);
    this.statusCode = statusCode;
    this.errorCode = errorCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class NotFoundError extends AppError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404, 'NOT_FOUND');
  }
}

class ValidationError extends AppError {
  constructor(message = 'Validation failed') {
    super(message, 400, 'VALIDATION_ERROR');
  }
}

// Async handler wrapper to catch async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// 404 handler for unknown routes
app.use((req, res, next) => {
  next(new NotFoundError('Route'));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Handle known operational errors
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      error: err.message,
      code: err.errorCode,
    });
  }

  // Handle specific error types
  if (err.name === 'SyntaxError' && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON in request body',
      code: 'INVALID_JSON',
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Invalid or missing authentication token',
      code: 'UNAUTHORIZED',
    });
  }

  // Generic error response (don't leak error details in production)
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message,
    code: 'INTERNAL_ERROR',
  });
});

// ============================================
// MOCK DATA
// ============================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================
// ROUTES
// ============================================

// Health check endpoint (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0',
  });
});

// Get all users with pagination and optional search
app.get('/users', userQuerySchema, asyncHandler(async (req, res) => {
  const { page = 1, limit = 10, search } = req.query;

  let filteredUsers = [...users];

  // Safe search with parameterized approach
  if (search) {
    const searchLower = search.toLowerCase();
    filteredUsers = filteredUsers.filter(user => 
      user.name.toLowerCase().includes(searchLower) ||
      user.email.toLowerCase().includes(searchLower)
    );
  }

  // Pagination
  const startIndex = (page - 1) * limit;
  const paginatedUsers = filteredUsers.slice(startIndex, startIndex + limit);

  // Redact sensitive information if needed
  const safeUsers = paginatedUsers.map(user => ({
    id: user.id,
    name: user.name,
    // Only show email to authorized users (implement auth check)
    // email: req.user?.canViewEmail ? user.email : undefined,
  }));

  res.json({
    data: safeUsers,
    pagination: {
      page,
      limit,
      total: filteredUsers.length,
      totalPages: Math.ceil(filteredUsers.length / limit),
    },
  });
}));

// Get single user by ID
app.get('/users/:id', userIdSchema, asyncHandler(async (req, res) => {
  const user = users.find(u => u.id === req.params.id);

  if (!user) {
    throw new NotFoundError('User');
  }

  res.json({
    id: user.id,
    name: user.name,
    // Consider whether to expose email
  });
}));

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = { app, server, AppError, NotFoundError, ValidationError };

