// Improved application with security best practices
// Includes error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Parse JSON with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ============================================
// ERROR HANDLING UTILITIES
// ============================================

/**
 * Custom application error class
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Async handler wrapper to catch async errors
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Validation error handler
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'fail',
      errors: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================
// INPUT VALIDATION SCHEMAS
// ============================================

const userQuerySchema = [
  query('id')
    .optional()
    .isInt({ min: 1, max: 999999 })
    .withMessage('ID must be a positive integer'),
  query('name')
    .optional()
    .trim()
    .escape()
    .isLength({ max: 100 })
    .withMessage('Name must be 100 characters or less'),
  query('email')
    .optional()
    .trim()
    .normalizeEmail()
    .isEmail()
    .withMessage('Invalid email format')
    .isLength({ max: 254 })
    .withMessage('Email must be 254 characters or less'),
];

const healthCheckSchema = [
  query('verbose')
    .optional()
    .isBoolean()
    .withMessage('Verbose must be a boolean value'),
];

// ============================================
// ROUTES
// ============================================

app.get('/health', healthCheckSchema, handleValidationErrors, (req, res) => {
  // Safe health check without exposing sensitive system info
  const healthStatus = {
    status: 'ok',
    timestamp: new Date().toISOString(),
  };

  // Only add uptime if explicitly requested and validated
  if (req.query.verbose === 'true') {
    healthStatus.uptime = Math.floor(process.uptime());
  }

  res.json(healthStatus);
});

app.get('/users', userQuerySchema, handleValidationErrors, asyncHandler(async (req, res) => {
  // Mock user data (in production, this would come from a database)
  // Using parameterized queries would be essential here
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter users based on validated query params
  let filteredUsers = [...users];

  if (req.query.id) {
    filteredUsers = filteredUsers.filter(u => u.id === parseInt(req.query.id, 10));
  }

  if (req.query.name) {
    // Safe case-insensitive search without regex injection risk
    const searchName = req.query.name.toLowerCase();
    filteredUsers = filteredUsers.filter(u => 
      u.name.toLowerCase().includes(searchName)
    );
  }

  if (req.query.email) {
    filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
  }

  res.json(filteredUsers);
}));

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res, next) => {
  next(new AppError(`Cannot find ${req.method} ${req.path} on this server`, 404));
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  // Default values
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error details (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    statusCode: err.statusCode,
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  // Handle specific error types
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      status: 'fail',
      message: 'Invalid or missing authentication token',
    });
