// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, param, query } = require('express-validator');

const app = express();

// ===================
// Security Middleware
// ===================

// Set security HTTP headers
app.use(helmet());

// Parse JSON bodies with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS configuration (adjust as needed for your use case)
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGINS || '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// ===================
// Data (replace with database in production)
// ===================
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
  { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
];

// ===================
// Helper Functions
// ===================

// Sanitize user data to prevent sensitive information leakage
const sanitizeUser = (user) => ({
  id: user.id,
  name: user.name,
  role: user.role,
  // Exclude email and other sensitive fields
});

// Async handler wrapper to catch async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ===================
// Routes
// ===================

// Health check endpoint (public)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Get all users with optional filtering
app.get('/users',
  [
    query('role').optional().isIn(['user', 'admin']).escape(),
  ],
  asyncHandler(async (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Filter by role if provided
    let result = users;
    if (req.query.role) {
      result = users.filter(u => u.role === req.query.role);
    }

    // Sanitize output - don't expose sensitive data
    const sanitizedUsers = result.map(sanitizeUser);
    res.json(sanitizedUsers);
  })
);

// Get single user by ID
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt(),
  ],
  asyncHandler(async (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const user = users.find(u => u.id === req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

